CREATE TABLE rule_recon_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),skill_rule_id bigint NOT NULL UNIQUE REFERENCES rule_skill(rule_id));
CREATE TABLE rule_recon_operation(rule_id bigint NOT NULL REFERENCES rule_recon_mechanic(rule_id),operation_code text NOT NULL CHECK(operation_code IN('scout-danger','spot-threat','spot-unusual-object','spot-out-of-place-person','remain-unseen','remain-unheard')),operation_group text NOT NULL CHECK(operation_group IN('observation','concealment')),display_order smallint NOT NULL CHECK(display_order>0),PRIMARY KEY(rule_id,operation_code),UNIQUE(rule_id,display_order));
COMMENT ON TABLE rule_recon_operation IS 'CE-SKILL-012 paired-source Recon observation and concealment capabilities without invented difficulty or opposed-check rules.';
